Define an \emph{explicit finitely generated abelian group} to be a group of the form
\begin{equation}\label{explicit-group}
\mathbb{Z}^d \times \mathbb{Z}_{N_1} \times \dots \times \mathbb{Z}_{N_m}
\end{equation}
for some (standard) natural numbers $d, m$ and (standard) positive integers $N_1,\dots,N_m$, where we use $\mathbb{Z}_N \coloneqq \mathbb{Z}/N\mathbb{Z}$ to denote the standard cyclic group of order $N$.

Also, we adopt the convention that an equation such as \eqref{tile-eq} is automatically false if one or more of the terms in that equation is undefined.}
\begin{equation}\label{tile-eq}
\mathrm{X} \oplus F = E
\end{equation}
where we view the tile $F$ and the set $E$ to be tiled as given data and the indeterminate variable $\mathrm{X}$ denotes an unknown subset of $G$.

\label{undecide}  Let $G$ be an (explicit) finitely generated abelian group, $F$ a finite subset of $G$, and $E$ a periodic subset of $G$.
\begin{itemize}
\item[(i)]  We say that the tiling equation $\operatorname{Tile}(F;E)$ is \emph{undecidable} if the assertion that there exists a solution $A \subset G$ to $\operatorname{Tile}(F;E)$, when phrased as a first-order sentence in ZFC, is not provable within the axiom system of ZFC.  By the G\"odel completeness theorem, this is equivalent to the assertion that $\operatorname{Tile}(F;E)_{{\mathfrak{U}}^*}$ is empty for some\footnote{In fact, in the specific context of undecidable tiling equations, one can show that $\operatorname{Tile}(F;E)_{{\mathfrak{U}}}$ is non-empty for the \emph{standard} universe ${\mathfrak{U}}$; see Appendix \ref{wang-app}.} universes ${\mathfrak{U}}^*$ of ZFC, but non-empty for some other universes.  We say that the tiling equation $\operatorname{Tile}(F;E)$ is \emph{decidable} if it is not undecidable.
\item[(ii)]  We say that the tiling equation $\operatorname{Tile}(F;E)$ is \emph{aperiodic} if, when working within the standard universe ${\mathfrak{U}}$ of ZFC, the equation $\operatorname{Tile}(F;E)$ admits a solution $A \subset G$, but that none of these solutions are periodic.  That is to say, $\operatorname{Tile}(F;E)_{\mathfrak{U}}$ is non-empty but contains no periodic sets.
\end{itemize}

In the language of convolutions, one can also write this tiling equation as $\mathds{1}_{\mathrm{X}_1} * \mathds{1}_{F_1} + \dots + \mathds{1}_{\mathrm{X}_J} * \mathds{1}_{F_J} = \mathds{1}_E$, where we use $\mathds{1}_A$ to denote the indicator function of $A$.}
\begin{equation}\label{multitile}
\biguplus_{j=1}^J \mathrm{X}_j \oplus F_j = E,
\end{equation}
where $A \uplus B$ denotes the disjoint union of $A$ and $B$ (equal to $A \cup B$ when $A,B$ are disjoint, and undefined otherwise).

\label{undecide-mult}  Let $G$ be an explicit finitely generated abelian group, $F_1,\dots,F_J$ be finite subsets of $G$ for some standard natural number $J$, and $E$ a periodic subset of $G$.
\begin{itemize}
\item[(i)]  We say that the tiling equation $\operatorname{Tile}(F_1,\dots,F_J;E)$ is \emph{undecidable} if the assertion that there exist subsets $A_1,\dots,A_J \subset G$ solving $\operatorname{Tile}(F_1,\dots,F_J;E)$, when phrased as a first-order sentence in ZFC, is not provable within the axiom system of ZFC. By the G\"odel completeness theorem, this is equivalent to the assertion that $\operatorname{Tile}(F_1,\dots,F_J;E)_{{\mathfrak{U}}^*}$ is non-empty for some universes ${\mathfrak{U}}^*$ of ZFC, but empty for some other universes. We say that $\operatorname{Tile}(F_1,\dots,F_J;E)$ is \emph{decidable} if it is not undecidable.
\item[(ii)]  We say that the tiling equation $\operatorname{Tile}(F_1,\dots,F_J;E)$ is \emph{aperiodic} if, when working within the standard universe ${\mathfrak{U}}$ of ZFC, the equation $\operatorname{Tile}(F_1,\dots,F_J;E)$ admits a solution $A_1,\dots,A_J \subset G$, but there are no solutions for which all of the $A_1,\dots,A_J$ are periodic. That is to say, $\operatorname{Tile}(F_1,\dots,F_J;E)_{\mathfrak{U}}$ is non-empty but contains no tuples of periodic sets.
\end{itemize}

\label{tilex}  Let $G$ be an explicit finitely generated abelian group, and let $G_0$ be a explicit finite abelian group.  The solutions $A$ to the tiling equation $\operatorname{Tile}(\{0\} \times G_0; G \times G_0)$ are precisely those sets which are graphs
\begin{equation}\label{af}
 A = \{ (n, f(n)) : n \in G \}
 \end{equation}
for an arbitrary function $f \colon G \to G_0$.  It is possible to impose additional conditions on $f$ by adding more tiling equations to this ``base'' tiling equation $\operatorname{Tile}(\{0\} \times G_0; G \times G_0)$.  For instance, if in addition $H$ is a subgroup of $G_0$ and $y+H$ is a coset of $H$ in $G_0$, solutions $A$ to the system of tiling equations
$$ \operatorname{Tile}(\{0\} \times G_0; G \times G_0), \operatorname{Tile}(\{0\} \times H; G \times (y+H))$$
are precisely sets $A$ of the form \eqref{af} where the function $f$ obeys the additional\footnote{In this particular case, the former tiling equation is redundant, being a consequence of the latter. However, we choose to retain the former equation in this example to illustrate the principle of imposing additional constraints on the function $f$ by the insertion of additional tiling equations.} constraint $f(n) \in y+H$ for all $n \in G$.    As a further example, if $-y_0, y_0$ are distinct elements of $G_0$, and $h$ is a non-zero element of $G$, then solutions $A$ to the system of tiling equations
$$ \operatorname{Tile}(\{0\} \times G_0; G \times G_0), \operatorname{Tile}(\{0,-h\} \times \{0\}; G \times \{-y_0,y_0\})$$
are precisely sets $A$ of the form \eqref{af} where the function $f$ takes values in $\{-y_0,y_0\}$ and obeys the additional constraint $f(n+h) = -f(n)$ for all $n \in G$. In all three cases one can verify that the system of tiling equations is decidable and not aperiodic.

\label{combine}  Let $J,M \geqslant 1$, let $G = \mathbb{Z}^d \times G_0$ be an explicit finitely generated abelian group for some explicit finite abelian group $G_0$.  Let $\mathbb{Z}_N$ be a cyclic group with $N>M$, and for each $m=1,\dots,M$ let $F_1^{(m)},\dots,F_J^{(m)}$ be finite non-empty subsets of $G$ and $E_0^{(m)}$ a subset of $G_0$.  Define the finite sets $\tilde F_1,\dots,\tilde F_J \subset G \times \mathbb{Z}_N$ and the set $\tilde E_0 \subset G_0 \times \mathbb{Z}_N$ by 
\begin{equation}\label{fj-stack}
 \tilde F_j \coloneqq \biguplus_{m=1}^M F_j^{(m)} \times \{m\}
 \end{equation}
and
\begin{equation}\label{e0-stack}
 \tilde E_0 \coloneqq \biguplus_{m=1}^M E_0^{(m)} \times \{m\}.
 \end{equation}
\begin{itemize}
\item[(i)]  The system $\operatorname{Tile}(F_1^{(m)},\dots,F_J^{(m)}; \mathbb{Z}^d \times E_0^{(m)}), m=1,\dots,M$ of tiling equations is aperiodic if and only if the tiling equation
$\operatorname{Tile}(\tilde F_1,\dots,\tilde F_J; \mathbb{Z}^d \times \tilde E_0)$ is aperiodic.
\item[(ii)]  The system $\operatorname{Tile}(F_1^{(m)},\dots,F_J^{(m)}; \mathbb{Z}^d \times E_0^{(m)}), m=1,\dots,M$ of tiling equations is undecidable if and only if the tiling equation
$\operatorname{Tile}(\tilde F_1,\dots,\tilde F_J; \mathbb{Z}^d \times \tilde E_0)$ is undecidable.
\end{itemize}

\label{main-function}  There exists an explicit finite abelian group $G_0$, a standard integer $M \geqslant 1$, and for each $m=1,\dots,M$ there exist (possibly empty) finite subsets $H_1^{(m)}, H_2^{(m)}$ of $\mathbb{Z}^2 \times \mathbb{Z}_2$ and (possibly empty sets) $F_1^{(m)}, F_2^{(m)}, E^{(m)} \subset G_0$ for $m=1,\dots,M$ such that the question of whether there exist  functions $f_1,f_2 \colon \mathbb{Z}^2 \times \mathbb{Z}_2 \to G_0$ that solve
the system of functional equations
\begin{equation}\label{func-eq}
\biguplus_{h_1 \in H_1^{(m)}} (F_1^{(m)} + f_1(n+h_1)) \uplus
\biguplus_{h_2 \in H_2^{(m)}} (F_2^{(m)} + f_2(n+h_2)) = E^{(m)}
\end{equation}
for all $n \in \mathbb{Z}^2\times \mathbb{Z}_2$ and $m=1,\dots,M$ is undecidable (when expressed as a first-order sentence in ZFC).

\label{main-hamming}  There exist  standard integers $N > 2$ and $D,M \geqslant 1$, and for each $m=1,\dots,M$ there exist shifts $h_1^{(m)}, h_2^{(m)} \in \mathbb{Z}^2$ and (possibly empty sets) $F_1^{(m)}, F_2^{(m)}, E^{(m)} \subset \mathbb{Z}_N^D$ for $m=1,\dots,M$ such that the question of whether there exist functions $f_1,f_2 \colon \mathbb{Z}^2 \to \{-1,1\}^D$ that solve
the system of functional equations
\begin{equation}\label{func-eq-1}
(F_1^{(m)} + \epsilon f_1(n+h_1^{(m)})) \uplus
(F_2^{(m)} + \epsilon f_2(n+h_2^{(m)})) = E^{(m)}
\end{equation}
for all $n \in \mathbb{Z}^2$, $m=1,\dots,M$, and $\epsilon=\pm 1$ is undecidable (when expressed as a first-order sentence in ZFC).

\label{main-linear}  There exist  standard integers $D \geqslant D_0 \geqslant 1$ and $M_1, M_2 \geqslant 1$, integer coefficients $a_{j,d}^{(m)} \in \mathbb{Z}$ for $j=1,2$, $d=1,\dots,D$, $m=1,\dots,M_j$, and shifts $h_d \in \mathbb{Z}^2$ for $d=1,\dots,D_0$ such that the question of whether there exist functions $f_{j,d} \colon \mathbb{Z}^2 \to \{-1,1\} \subset \mathbb{Z}$ for $j=1,2$ and $d=1,\dots,D$ that solve
the system of linear functional equations
\begin{equation}\label{func-eq-2}
\sum_{d=1}^D a_{j,d}^{(m)} f_{j,d}(n) = 0
\end{equation}
for all $n \in \mathbb{Z}^2$, $j=1,2$, and $m = 1,\dots,M_j$, as well as the system of linear functional equations
\begin{equation}\label{func-eq-3}
f_{2,d}(n+h_d) = - f_{1,d}(n)
\end{equation}
for all $n \in \mathbb{Z}^2$ and $d=1,\dots,D_0$, is undecidable (when expressed as a first-order sentence in ZFC).

\label{main-boolean}  There exist standard integers $D, L \geqslant 1$, shifts $h_1,\dots,h_L \in \mathbb{Z}^2$, and a set $\Omega \subset \{-1,1\}^{DL}$ such that the question of whether there exist functions $f_d \colon \mathbb{Z}^2 \to \{-1,1\}$, $d=1,\dots,D$ that solve the constraint
\begin{equation}\label{boolean}
(f_d(n+h_l))_{d=1,\dots,D; l=1,\dots,L} \in \Omega 
\end{equation}
for all $n \in \mathbb{Z}^2$ is undecidable (when expressed as a first-order sentence in ZFC).

\label{tile-function}  Let $G$ be an explicit finitely generated abelian group, let $G_1$ be an explicit finite abelian group, let $J, M \geqslant 1$ and $N > J$ be standard natural numbers, and suppose that for each $j=1,\dots,J$ and $m=1,\dots,M$ one is given a (possibly empty) finite subset $H_j^{(m)}$ of $G$ and a (possibly empty) subset $F_j^{(m)}$ of $G_1$.  For each $m=1,\dots,M$, assume also that we are given a subset $E^{(m)}$ of $G_1$.  We adopt the abbreviations
\begin{align*}
    [[a]] &\coloneqq \{a\} \times G_1 \subset \mathbb{Z}_N \times G_1 \\
    [[a,b]] &\coloneqq \{ n \in \mathbb{Z}: a\leqslant n \leqslant b\} \times G_1\subset \mathbb{Z}_N\times G_1
\end{align*} 
for integers $a \leqslant b$.  Then the following are equivalent:
\begin{itemize}
\item[(i)]  The system of tiling equations
\begin{equation}\label{tile-1}
\operatorname{Tile}\left( \left( -H_j^{(m)} \times \{0\} \times F_j^{(m)} \uplus \{0\} \times [[j]])\right)_{j=1}^J; G \times (\{0\} \times E^{(m)} \uplus [[1,J]]) \right)
\end{equation}
for all $m=1,\dots,M$, together with the tiling equations
\begin{equation}\label{tile-2}
\operatorname{Tile}\left( \left( \{0\} \times [[\sigma(j)]] \right)_{j=1}^J; G \times [[1,J]] \right)
\end{equation}
for every permutation $\sigma \colon \{1,\dots,J\} \to \{1,\dots,J\}$ of $\{1,\dots,J\}$, admit a solution.
\item[(ii)]  There exist $f_j \colon G \to G_1$ for $j=1,\dots,J$ that obey the system of functional equations
\begin{equation}\label{func-eq-stack}
\biguplus_{j=1}^J \biguplus_{h_j \in H_j^{(m)}} (F_j^{(m)} + f_j(n+h_j)) = E^{(m)} 
\end{equation}
for all $n \in G$ and $m=1,\dots,M$.
\end{itemize}

\begin{align*}
    [[a]] &\coloneqq \{a\} \times G_1 \subset \mathbb{Z}_N \times G_1 \\
    [[a,b]] &\coloneqq \{ n \in \mathbb{Z}: a\leqslant n \leqslant b\} \times G_1\subset \mathbb{Z}_N\times G_1
\end{align*}

\begin{align*}
    A \oplus \left(  (-H \times \{0\} \times F) \uplus \{0\} \times \{1\} \times G_1)\right) &= G \times (\{0\} \times E \uplus \{1\} \times G_1) \\
A \oplus \{0\} \times \{1\} \times G_1 &= G \times \{1\} \times G_1
\end{align*}

 To understand this equivalence, the reader may wish to begin by verifying two simplified special cases of this equivalence.  Firstly, the two (trivially true) statements
\begin{itemize}
    \item[(i')]  There exist a function $f \colon \mathbb{Z}^2 \to \{-1,1\}^2$ solving the equation $$H + \epsilon f(n) = H$$ for all $n \in \mathbb{Z}^2$ and $\epsilon = \pm 1$, where $H \coloneqq \{ (y_1,y_2) \in \mathbb{Z}_N^2: y_1+y_2=0\}$.
    \item[(ii')]  There exist functions $f_1,f_2 \colon \mathbb{Z}^2 \to \{-1,1\}$ solving the equation $$f_1(n)+f_2(n) = 0$$ for all $n \in \mathbb{Z}^2$.
\end{itemize}
can be easily seen to be equivalent after making the substitution $f(n) = (f_1(n), f_2(n))$.  Secondly, for any $h \in \mathbb{Z}^2$, the two (trivially true) statements
\begin{itemize}
    \item[(i'')]  There exist a functions $f_1,f_2 \colon \mathbb{Z}^2 \to \{-1,1\}$ solving the equation $$(\{0\} + \epsilon f_1(n)) \uplus (\{0\} + \epsilon f_2(n+h)) = \{-1,1\}$$ for all $n \in \mathbb{Z}^2$ and $\epsilon = \pm 1$.
    \item[(ii'')]  There exist functions $f_1,f_2 \colon \mathbb{Z}^2 \to \{-1,1\}$ solving the equation $$f_2(n+h) = -f_1(n)$$ for all $n \in \mathbb{Z}^2$.
\end{itemize}
are also easily seen to be equivalent (the solution sets $(f_1,f_2)$ for (i'') and (ii'') are identical).

let $f_j \colon \mathbb{Z}^2 \to \{-1,1\}^D$ be the function
\begin{equation}\label{fjn}
 f_j(n) \coloneqq (f_{j,1}(n), \dots, f_{j,D}(n))
 \end{equation}
for $n \in \mathbb{Z}^2$ and $j=1,2$, where we now view the Hamming cube $\{-1,1\}^D$ as lying in $\mathbb{Z}_N^D$.

\label{antipode}  There exist standard integers $D_0 \geqslant 2$ and $M_1,M_2 \geqslant 1$, shifts $h_1,\dots,h_{D_0} \in \mathbb{Z}^2$, and vectors $\epsilon_j^{(m)} \in \{-1,1\}^{D}$ for $j=1,2$ and $m=1,\dots,M_j$ such that the question of whether there exist functions $f_{j,d} \colon \mathbb{Z}^2 \to \{-1,1\}$, for $j=1,2$, $d=1,\dots,D_0$ that solve the constraints
\begin{equation}\label{antipode-1}
(f_{j,d}(n))_{d=1,\dots,D_0} \not \in \{ -\epsilon_j^{(m)}, \epsilon_j^{(m)} \}
\end{equation}
for all $n \in \mathbb{Z}^2$, $j=1,2$, $m =1,\dots,M_j$, as well as the constraints
\begin{equation}\label{antipode-2}
f_{2,d}(n+h_d) = - f_{1,d}(n)
\end{equation}
for all $n \in \mathbb{Z}^2$ and  $d = 1,\dots,D_0$, is undecidable (when expressed as a first-order sentence in ZFC).

  As a simple example of this equivalence (with $D_0=4$ and $\epsilon_1=\dots=\epsilon_4=1$), given a triple $(y_1,y_2,y_3,y_4) \in \{-1,1\}^4$, we see that the following claims are equivalent:
\begin{itemize}
    \item [(a')] $(y_1,y_2,y_3,y_4) \not \in \{ (-1,-1,-1,-1), (+1,+1,+1,+1) \}$.
    \item[(b')] $y_1+y_2+y_3+y_4 \in \{-2,0,+2\}$.
    \item[(c')] There exist $y_5, y_6 \in \{-1,1\}$ such that $y_1+y_2+y_3+y_4+y_5+y_6 = 0$.
\end{itemize}

\label{combine'}  Let $J,M,d \geqslant 1$ and $N>M$ be standard natural numbers.  
For each $m=1,\dots,M$, let $F_1^{(m)},\dots,F_J^{(m)}$ be finite non-empty subsets of $\mathbb{Z}^d$, and let $E^{(m)}$ be a periodic subset of $\mathbb{Z}^d$.  Define the finite sets $\tilde F_1,\dots,\tilde F_J \subset \mathbb{Z}^d \times \{1,\dots, M\}$ and the periodic set $\tilde E \subset \mathbb{Z}^d \times \mathbb{Z}$ by 
\begin{equation}\label{fj-stack'}
 \tilde F_j \coloneqq \biguplus_{m=1}^M F_j^{(m)} \times \{m\}
 \end{equation}
and
\begin{equation}\label{e0-stack'}
 \tilde E \coloneqq  \biguplus_{m=1}^M E^{(m)} \times (N\mathbb{Z}+m ).
 \end{equation}
\begin{itemize}
\item[(i)]  The system $\operatorname{Tile}(F_1^{(m)},\dots,F_J^{(m)}; E^{(m)}), m=1,\dots,M$ of tiling equations is aperiodic if and only if the tiling equation
$\operatorname{Tile}(\tilde F_1,\dots,\tilde F_J; \tilde E)$ is aperiodic.
\item[(ii)]  The system $\operatorname{Tile}(F_1^{(m)},\dots,F_J^{(m)}; E^{(m)}), m=1,\dots,M$ of tiling equations is undecidable if and only if the tiling equation
$\operatorname{Tile}(\tilde F_1,\dots,\tilde F_J; \tilde E)$ is undecidable.
\end{itemize}

\label{tile-function'} 
Let $G$ be an explicitly finitely generated abelian group, and $G_1=\mathbb{Z}_{N_1}\times\dots\times \mathbb{Z}_{N_k}$ be an explicit finite abelian group with $N_1,\dots,N_k \geqslant 5$. Let $J,M \geqslant 1$ be standard natural numbers, and $\Lambda, R$ be as in \ref{rigid-tile}.
Suppose that for each $j=1,\dots,J$ and $m=1,\dots,M$ one is given a (possibly empty) finite subset $H_j^{(m)}$ of $G$ and a (possibly empty) subset $F_j^{(m)}$ of $\mathbb{Z}^k$.  For each $m=1,\dots,M$, assume also that we are given a subset $E_1^{(m)}$ of $G_1$ and let $E^{(m)} \coloneqq \pi^{-1}(E_1^{(m)})$, where $\pi \colon \mathbb{Z}^k \to G_1$ is the quotient homomorphism (with kernel $\Lambda$).
 We adopt the abbreviations
$$ [[a]] \coloneqq \{a\} \times R ; \quad [[a,b]] \coloneqq  \{ n \in \mathbb{Z}: a\leqslant n \leqslant b\} \times R \subset \mathbb{Z}\times \mathbb{Z}^k $$
for integers $a \leqslant b$.  Let $N>J$. Then the following are equivalent:
\begin{itemize}
\item[(i)]  The system of tiling equations
\begin{equation}\label{tile-1'}
\operatorname{Tile}\left( \left( -H_j^{(m)} \times \{0\} \times F_j^{(m)} \uplus \{0\} \times [[j]])\right)_{j=1}^J; \tilde E^{(m)} \right)
\end{equation}
for all $m=1,\dots,M$, together with the tiling equations
\begin{equation}\label{tile-2'}
\operatorname{Tile}\left( \left( \{0\} \times [[\sigma(j)]] \right)_{j=1}^J; G \times ([[1,J]]\oplus N\mathbb{Z}\times\Lambda ) \right)
\end{equation}
for every permutation $\sigma \colon \{1,\dots,J\} \to \{1,\dots,J\}$ of $\{1,\dots,J\}$, admit a solution, where
$$ \tilde E^{(m)} \coloneqq G \times (N\mathbb{Z} \times E^{(m)} \uplus [[1,J]] \oplus N\mathbb{Z}\times \Lambda ).$$
\item[(ii)]  There exist $f_j \colon G \to G_1$ for $j=1,\dots,J$ that obey the system of functional equations
\begin{equation}\label{func-eq-stack'}
\biguplus_{j=1}^J \biguplus_{h_j \in H_j^{(m)}} (F_j^{(m)} + f_j(n+h_j)) = E_1^{(m)} 
\end{equation}
for all $n \in G$ and $m=1,\dots,M$.
\end{itemize}

\label{main-function'}  There exists an explicit finite abelian group $G_0$, a standard integer $M \geqslant 1$, and for each $m=1,\dots,M$ there exist (possibly empty) finite subsets $H_1^{(m)}, H_2^{(m)}$ of $\mathbb{Z}^2 \times \mathbb{Z}$ and (possibly empty sets) $F_1^{(m)}, F_2^{(m)}, E^{(m)} \subset G_0$ for $m=1,\dots,M$ such that the question of whether there exist  functions $g_1,g_2 \colon \mathbb{Z}^2 \times \mathbb{Z} \to G_0$ that solve
the system of functional equations
\begin{equation}\label{func-eq'}
\biguplus_{h_1 \in H_1^{(m)}} (F_1^{(m)} + g_1(n+h_1)) \uplus
\biguplus_{h_2 \in H_2^{(m)}} (F_2^{(m)} + g_2(n+h_2)) = E^{(m)}
\end{equation}
for all $n \in \mathbb{Z}^2\times \mathbb{Z}$ and $m=1,\dots,M$ is undecidable (when expressed as a first-order sentence in ZFC).

  We repeat the arguments from Section \ref{hamming-sec}.  Let $N$, $D$, $M$, $h_1^{(m)}$, $h_2^{(m)}$, $F_1^{(m)}$, $F_2^{(m)}$, $E^{(m)}$ be as in  Theorem~\ref{main-hamming}.  We recall the systems \eqref{sys-1}, \eqref{sys-2} of functional equations, introduced in Section~\ref{hamming-sec}.

As before, for each $d=1,\dots,D$, let $\pi_d \colon \mathbb{Z}_N^D \to \mathbb{Z}_N$ denote the $d^{\mathrm{th}}$ coordinate projection.
We write elements of $\mathbb{Z}^2 \times \mathbb{Z}_2$ as $(n,t)$ with $n \in \mathbb{Z}^2$ and $t \in \mathbb{Z}_2$ and   elements of $\mathbb{Z}^2 \times \mathbb{Z}$ as $(n,z)$ with $n \in \mathbb{Z}^2$ and $z \in \mathbb{Z}$.

For a pair of functions $ g_1, g_2 \colon \mathbb{Z}^2 \times \mathbb{Z} \to \mathbb{Z}_N^D$, consider the system of functional equations
\begin{equation}\label{sys-1'}
\left(\pi_d^{-1}(\{0\}) +  g_j(n,z)\right) \uplus 
\left(\pi_d^{-1}(\{0\}) +  g_j(n,z+1)\right) = \pi_d^{-1}(\{-1,1\}) 
\end{equation}
for $d=1,\dots,D$ and $j=1,2$, as well as the equations
\begin{equation}\label{sys-2'}
\left(F_1^{(m)} +  g_1((n,z)+(h_1^{(m)},0))\right) \uplus
\left(F_2^{(m)} +  g_2((n,z)+(h_2^{(m)},0))\right) = E^{(m)}
\end{equation}
for $m=1,\dots,M$.  It will suffice to establish (using an argument valid in every universe of ZFC) the equivalence of the following two claims:

\begin{itemize}
\item[(i)]  There exist functions $\tilde f_1, \tilde f_2 \colon \mathbb{Z}^2 \times \mathbb{Z}_2 \to \mathbb{Z}_N^D$ solving the systems \eqref{sys-1}, \eqref{sys-2}.
\item[(ii)] There exist functions $ g_1,  g_2 \colon \mathbb{Z}^2 \times \mathbb{Z} \to \mathbb{Z}_N^D$ solving the systems \eqref{sys-1'}, \eqref{sys-2'}.
 \end{itemize}

 Indeed, if (i) is equivalent to (ii), by Section~\ref{hamming-sec}, (ii) is equivalent to the existence of functions $f_1,f_2\colon \mathbb{Z}^2\to \{-1,1\}^D$ solving the system \eqref{func-eq-1}. Hence Theorem~\ref{main-hamming} implies Theorem~\ref{main-function'}.

 It  therefore remains to show that (i) and (ii) are equivalent.
 Suppose first that $\tilde f_1, \tilde f_2 \colon \mathbb{Z}^2 \times \mathbb{Z}_2 \to \mathbb{Z}_N^D$ solve the systems \eqref{sys-1}, \eqref{sys-2}. Then we can define $ g_1,  g_2 \colon \mathbb{Z}^2 \times \mathbb{Z} \to \mathbb{Z}_N^D$
 \begin{equation*}
     g_j(n,z)=\tilde f_j(n, z\mod 2),\quad j=1,2
 \end{equation*}
 which solve systems \eqref{sys-1'}, \eqref{sys-2'}.
